  --color-red-500: #ef4444;
  --color-blue: blue;
  --tab-size-github: 8;
  --tab-size-deep-nested: 16;
  --text-sm: 0.875rem;
  --text-sm--line-height: 1.25rem;
  --text-lg: 1.125rem;
  --text-lg--line-height: 1.75rem;
  --text-lg--letter-spacing: 0.01em;
  --leading-tight: 1.25;
  --leading-6: 1.5rem;
  --opacity-half: 0.5;
  --value-2\.5: two-and-a-half;
  --value-1\/2: one-half;
  --empty-none: ;
}
@theme inline {
  --inline-a: 1px;
  --inline-a--extra: 2px;
}
@utility mrg-* {
  margin: --spacing(--value(number));
  margin: --value([length], [percentage]);
}
@utility -mrg-* {
  margin: --spacing(--value(number) * -1);
  margin: calc(--value([length], [percentage]) * -1);
}

